const tabId = 583778164;

// Let's inspect the page content in more detail: filters, sort options, etc.
const info = await browserjs(tabId, () => {
  // Look for sort dropdown or buttons
  const sortSelect = document.querySelector('select[data-automation-id="sort-select"], select#sort-by, [data-automation-id*="sort"]');
  const sortText = sortSelect ? sortSelect.outerHTML : null;

  // Look for filter headers or filter buttons
  const filterElements = Array.from(document.querySelectorAll('button, div, span, label')).filter(el => {
    const t = el.textContent?.trim().toLowerCase();
    return t === 'sort' || t === 'color' || t === 'price' || t === 'sort by' || t.startsWith('sort by:');
  }).map(el => ({ tag: el.tagName, text: el.textContent?.trim(), id: el.id, className: el.className, automationId: el.getAttribute('data-automation-id') }));

  // Check product count and product titles
  const products = Array.from(document.querySelectorAll('[data-automation-id="product-title"], .product-title, [data-automation-id="product-card"]')).map(el => el.textContent?.trim());

  return { sortText, filterElements: filterElements.slice(0, 15), productCount: products.length, sampleProducts: products.slice(0, 5) };
});

console.log(JSON.stringify(info, null, 2));

