  const headers = Array.from(document.querySelectorAll('[data-automation-id*="filter"], [data-automation-id*="accordion"], .filter-accordion, aside, [aria-label*="filter" i]')).map(el => ({
    text: el.textContent?.trim().slice(0, 100),
    dataAuto: el.getAttribute('data-automation-id'),
    tag: el.tagName
  }));

  // Specifically check for color and price filters
  const allButtons = Array.from(document.querySelectorAll('button')).map(b => ({
